package com.meterflow.payments;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="dunning_cases")public class DunningCase{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(nullable=false,unique=true)private UUID invoiceId;@Column(nullable=false)private String customerId;@Column(nullable=false)private String status="RETRYING";@Column(nullable=false)private int attempt=0;@Column private Instant nextAttemptAt;@Column(nullable=false)private Instant createdAt=Instant.now();protected DunningCase(){}public DunningCase(UUID i,String c){invoiceId=i;customerId=c;nextAttemptAt=Instant.now().plus(Duration.ofDays(1));}public UUID getId(){return id;}public UUID getInvoiceId(){return invoiceId;}public String getCustomerId(){return customerId;}public String getStatus(){return status;}public int getAttempt(){return attempt;}public Instant getNextAttemptAt(){return nextAttemptAt;}public Instant getCreatedAt(){return createdAt;}public void failed(){attempt++;if(attempt>=3){status="SUSPENDED";nextAttemptAt=null;}else{status="PAST_DUE";nextAttemptAt=createdAt.plus(Duration.ofDays(attempt==1?3:7));}}public void paid(){status="REACTIVATED";nextAttemptAt=null;}}
